insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802,'  '))$$,'P0001','Record a rejection reason between 3 and 1000 characters','Rejection requires a reason');
insert into tap_results select lives_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'Owner can reject the pending measured request');
insert into tap_results select is((select state from public.stock_issues where id=pg_temp.i(802)),'rejected','The original request becomes rejected, not deleted');
insert into tap_results select is((select quantity from public.stock_issues where id=pg_temp.i(802)),0.125::numeric,'Rejected request retains original measured quantity');
insert into tap_results select is((select reason from public.stock_issues where id=pg_temp.i(802)),'TEST original request retained','Rejected request retains original explanation');
insert into tap_results select is((select quantity from public.branch_inventory where branch_id=pg_temp.i(101) and product_id=pg_temp.i(312)),10::numeric,'Rejecting a 125 ml hold request does not deduct liquid');
insert into tap_results select is((select count(*)::integer from public.stock_holds where source_id=pg_temp.i(802)),0,'Rejected request creates no held goods');
insert into tap_results select is(pg_temp.report()->'totals'->>'documentedLossCentavos','250','The existing documented loss value is unchanged');
insert into tap_results select is(pg_temp.report()->'totals'->>'lossRows','1','A rejected request creates no posted loss');
insert into tap_results select is(pg_temp.controls()->>'issueCount','0','Rejected request leaves the pending list');
insert into tap_results select is(pg_temp.controls()->>'rejectedCount','1','Rejection remains in retained decision history');
insert into tap_results select is(pg_temp.controls()->'rejected'->0->>'base_unit','liter','Retained history carries the actual measurement');
insert into tap_results select is((pg_temp.controls()->'rejected'->0->>'quantity')::numeric,0.125::numeric,'Retained history preserves exact rejected ml quantity');
insert into tap_results select is(pg_temp.controls()->'rejected'->0->>'decided_name','Owner','Decision history retains the recorded owner name');
insert into tap_results select is(pg_temp.controls()->'rejected'->0->>'rejection_reason','TEST owner checked mistaken quantity','Decision history retains the rejection evidence');
insert into tap_results select is(public.agri_command('reject_stock_issue',pg_temp.reject(901,802))->>'duplicate','true','Identical original-ID rejection retry is a duplicate');
insert into tap_results select is((select count(*)::integer from public.stock_control_events where action='reject_stock_issue'),1,'Original rejection retry creates one event');
insert into tap_results select is((select count(*)::integer from public.audit_events where action='reject_stock_issue'),1,'Original rejection retry creates one audit record');
insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802,'TEST changed evidence under the same ID'))$$,'P0001','Stock-issue decision ID conflict','Changed evidence under the original decision ID is rejected');
insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(902,802))$$,'P0001','This request was already rejected. Refresh its retained history','A second decision ID cannot reject the same issue again');
insert into tap_results select throws_ok($$select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(802),'reason','TEST attempted approval after rejection'))$$,'P0001','This request was rejected. Submit a new correct request; rejected evidence cannot change stock','Rejected request can never be approved');
insert into tap_results select is(public.agri_command('record_stock_issue',pg_temp.issue(802,312,'0.125','hold'))->>'duplicate','true','Original submission retry acknowledges without reopening rejection');
insert into tap_results select is((select state from public.stock_issues where id=pg_temp.i(802)),'rejected','Submission retry leaves the terminal rejected state intact');
insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(903,801))$$,'P0001','Approved stock issues require owner reconciliation, not rejection','Rejection cannot undo an approved stock movement');
insert into saved values('first',pg_temp.controls());insert into saved values('second',public.agri_command('stock_controls',pg_temp.ctx()||jsonb_build_object('rejectedCursor',(select data->'rejectedNext' from saved where name='first'))));
insert into tap_results select is((select data->>'rejectedCount' from saved where name='first'),'52','All rejected records are counted beyond fifty');
insert into tap_results select is((select jsonb_array_length(data->'rejected') from saved where name='first'),50,'Rejected history first page is bounded');
insert into tap_results select is((select jsonb_array_length(data->'rejected') from saved where name='second'),2,'Rejected history cursor reaches the remaining records');
insert into tap_results select is((select count(distinct e->>'decision_id')::integer from saved s cross join lateral jsonb_array_elements(s.data->'rejected')e),52,'Rejected decisions neither skip nor duplicate across pages');
insert into tap_results select ok((select data->'rejectedNext'='null'::jsonb from saved where name='second'),'Completed history page has no next cursor');
insert into tap_results select is(pg_temp.report()->'totals'->>'documentedLossCentavos','250','Many rejected requests still leave documented loss value unchanged');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx()||'{"rejectedCursor":{"at":"2026-01-01"}}'::jsonb)$$,'P0001','Invalid rejected-issue position. Refresh stock controls','Malformed rejected history cursor is refused');
insert into tap_results select is((select count(*)::integer from public.payments),0,'Rejection and retries create no cash payment');
insert into tap_results select throws_ok($$update public.stock_issues set state='pending' where id=pg_temp.i(802)$$,'P0001',null,'A rejected request cannot be reopened by ordinary SQL maintenance');
insert into tap_results select throws_ok($$delete from public.stock_issues where id=pg_temp.i(802)$$,'P0001',null,'Rejected original evidence cannot be deleted');
insert into tap_results select is((select r->>'decided_name' from jsonb_array_elements(pg_temp.controls()->'rejected')r where r->>'id'=pg_temp.i(802)::text),(null)::text,'An old decision outside the first page remains on later pages');
insert into tap_results select is((select r->>'decided_name' from jsonb_array_elements(public.agri_command('stock_controls',pg_temp.ctx()||jsonb_build_object('rejectedCursor',(select data->'rejectedNext' from saved where name='first')))->'rejected')r where r->>'id'=pg_temp.i(802)::text),'Owner','Later staff-name edits do not rewrite original decision identity');
insert into tap_results select is((select sum(quantity) from public.inventory_movements where branch_id=pg_temp.i(101) and product_id=pg_temp.i(311)),(select quantity from public.branch_inventory where branch_id=pg_temp.i(101) and product_id=pg_temp.i(311)),'The rope stock ledger and projection still agree');
