begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.payload(n integer) returns jsonb language sql as $$select jsonb_build_object('version',1,'transactionId',pg_temp.i(n),'organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'deviceId',pg_temp.i(501),'cashierId',auth.uid(),'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and device_id=pg_temp.i(501) and closed_at is null),'occurredAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',75000,'cashReceived',100000,'items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301),'unitId',pg_temp.i(401),'batchId',null,'name','Grower feeds','unitName','Sack','quantity','0.5','factor','50','unitPrice',150000,'unitCost',120000,'priceVersion',1,'lineTotal',75000)))$$;

create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.transfer_receipt(q text default '30') returns jsonb language sql as $$select pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity',q,'heldQuantity','10','reason','TEST physical count: 30 saleable, 10 damaged, 10 missing')$$;
create function pg_temp.stock(b integer default 101) returns text language sql as $$select quantity::text from public.branch_inventory where branch_id=pg_temp.i(b) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.plan(saleid integer default 701) returns jsonb language sql as $$select public.agri_command('partial_refund_plan',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid)))$$;
create function pg_temp.refund(ident integer,q text default '0.2',t text default '0',d text default 'not_returned',saleid integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(ident),'shiftId',(select id from public.cashier_shifts where closed_at is null and branch_id=pg_temp.i(101)),'reference','TEST signed partial refund','reason','TEST inspected physical return and original cash amount','physicalConfirmed',true,'expectedRefundVersion',pg_temp.plan(saleid)->'version','expectedAmount',round((pg_temp.plan(saleid)->'lines'->0->>'lineTotal')::numeric*((pg_temp.plan(saleid)->'lines'->0->>'refundedQuantity')::numeric+q::numeric)/(pg_temp.plan(saleid)->'lines'->0->>'quantity')::numeric)::bigint-(pg_temp.plan(saleid)->'lines'->0->>'refundedAmount')::bigint,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity',q,'returnedQuantity',t,'disposition',d)))$$;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;


create function pg_temp.issue(n integer,p integer,q text,d text default 'write_off') returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(n),'productId',pg_temp.i(p),'batchId',null,'quantity',q,'category','damage','disposition',d,'reason','TEST original request retained')$$;
create function pg_temp.reject(n integer,s integer,note text default 'TEST owner checked mistaken quantity') returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('decisionId',pg_temp.i(n),'issueId',pg_temp.i(s),'reason',note)$$;
create function pg_temp.controls() returns jsonb language sql as $$select public.agri_command('stock_controls',pg_temp.ctx())$$;
create function pg_temp.report() returns jsonb language sql as $$select public.agri_command('stock_loss_report',pg_temp.ctx())$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('receive_stock',pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(850),'source','purchase','reference','TEST rejection opening','items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(311),'unitId',pg_temp.i(414),'quantity','1'),jsonb_build_object('productId',pg_temp.i(312),'unitId',pg_temp.i(415),'quantity','20'))));
select public.agri_command('record_stock_issue',pg_temp.issue(801,311,'0.25'));select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(801),'reason','TEST actual quarter meter damaged'));
select public.agri_command('record_loss_cost',pg_temp.ctx()||jsonb_build_object('lossKey',(select 'movement:'||id from public.inventory_movements where source_id=pg_temp.i(801) and kind='loss'),'costEvidenceId',pg_temp.i(851),'expectedCostId',null,'unitId',pg_temp.i(414),'unitCostCentavos','100000','zeroCostConfirmed',false,'reference','TEST roll cost invoice','reason','TEST one documented 100 meter roll'));
select public.agri_command('record_stock_issue',pg_temp.issue(802,312,'0.125','hold'));
select pg_temp.login(13);insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'42501','Only the owner can reject a stock issue','Stock staff cannot reject a pending issue');
select pg_temp.login(12);insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'42501',null,'Cashier cannot reject a pending issue');
select pg_temp.login(14);insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'42501',null,'Another branch manager cannot reject this issue');
select pg_temp.login(15);insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'42501',null,'Another organization cannot reject or read the request');
select pg_temp.login(11);
select pg_temp.login(16);insert into tap_results select throws_ok($$select public.agri_command('reject_stock_issue',pg_temp.reject(901,802))$$,'P0001','Stock-issue decision ID conflict','Another owner cannot reuse the first owner decision ID');
select pg_temp.login(11);
do $$begin for n in 1..51 loop perform public.agri_command('record_stock_issue',pg_temp.issue(2000+n,311,'0.001'));perform public.agri_command('reject_stock_issue',pg_temp.reject(3000+n,2000+n));end loop;end$$;
reset role;
update public.staff_memberships set name='Renamed owner' where organization_id=pg_temp.i(1) and user_id=pg_temp.i(11);
set local role authenticated;select pg_temp.login(11);
reset role;select line from tap_results;select * from finish();rollback;

